                return 16
        else:
            if d != 64:
                return 16
        i = 0
        while i < 64:
            v = byte(s, target_at + i)
            if unhex(v) > 15:
                return 16
            store(w, 192 + i, v)
            if sequence == 0:
                store(w, 128 + i, 0)
            else:
                v = byte(s, expected_at + i)
                if unhex(v) > 15:
