            swap_records(w, 1536 + root * 96, 1536 + child * 96)
            root = child
        else:
            active = 0
    return 0

def sort_records(w:mutbuf, count:u64) -> u64:
    start = count >> 1
    while start > 0:
        start = start - 1
        sift(w, start, count)
    end = count
    while end > 1:
        end = end - 1
        swap_records(w, 1536, 1536 + end * 96)
        sift(w, 0, end)
    return 0

